css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; bottom: 50%; left: 50%; width: calc(var(--loader-size) * .045); height: calc(var(--loader-size) * .22); margin-left: calc(var(--loader-size) * -.0225); background: linear-gradient(var(--accent-2), var(--accent)); border-radius: 3px; transform-origin: 50% 100%; animation: eq calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader span:nth-child(1) { transform: rotate(0deg); animation-delay: 0s; }
.loader span:nth-child(2) { transform: rotate(30deg); animation-delay: calc(var(--loader-speed) * .08); }
.loader span:nth-child(3) { transform: rotate(60deg); animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-child(4) { transform: rotate(90deg); animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(5) { transform: rotate(120deg); animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-child(6) { transform: rotate(150deg); animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(7) { transform: rotate(180deg); animation-delay: calc(var(--loader-speed) * .48); }
.loader span:nth-child(8) { transform: rotate(210deg); animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(9) { transform: rotate(240deg); animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-child(10) { transform: rotate(270deg); animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(11) { transform: rotate(300deg); animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-child(12) { transform: rotate(330deg); animation-delay: calc(var(--loader-speed) * .08); }
@keyframes eq { 0%, 100% { scale: 1 .45; } 50% { scale: 1 1.25; } }
